/* ─── reader — layout-faithful document ─────────────────────────── */
function openPaper(id) { const pl = activePlan(); pl.activeId = id; state.selPara = null; state.selSent = null; save(); go('reader'); }

function buildFlat() {
  const flat = []; let bid = 0, pi = 0;
  DOC.pageList.forEach(pg => pg.blocks.forEach(b => {
    b._bid = bid++;
    if (b.k === 'p') { b._pi = pi++; flat.push({ bid: b._bid, pi: b._pi, sec: b.sec, zh: b.zh }); }
  }));
  return flat;
}
const parseSid = sid => { const m = /^p(\d+)([ec])(\d+)$/.exec(sid || ''); return m ? [+m[1], m[2], +m[3]] : null; };
/* split into sentences; terminal punctuation stays with the sentence */
function splitEn(text) {
  const out = []; let start = 0;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c !== '.' && c !== '!' && c !== '?') continue;
    let j = i + 1;
    while (j < text.length && /[.!?"'”’)\]]/.test(text[j])) j++;
    if (j >= text.length || /\s/.test(text[j])) { out.push(text.slice(start, j)); start = j; i = j - 1; }
  }
  if (start < text.length) out.push(text.slice(start));
  return out.filter(s => s.trim().length);
}
function splitZh(text) {
  const parts = text.match(/[^。！？；…]+[。！？；…]*/g) || [text];
  return parts.filter(s => s.trim().length);
}
function sentHTML(text, lang, pi) {
  const arr = lang === 'zh' ? splitZh(text) : splitEn(text);
  return arr.map((s, i) => {
    const sid = 'p' + pi + (lang === 'zh' ? 'c' : 'e') + i;
    const label = s.trim().slice(0, 80);
    return '<span class="sn" data-sid="' + sid + '" data-slang="' + lang + '" tabindex="0" role="button" aria-label="' +
      esc(label) + '">' + esc(s) + '</span>';
  }).join('');
}
function cellHTML(c) {
  if (c.en === c.zh) return '<span class="b-any">' + esc(c.en) + '</span>';
  return '<span class="b-en">' + esc(c.en) + '</span><span class="b-zh">' + esc(c.zh) + '</span>';
}
function blockHTML(b) {
