      '<span class="b-en">' + esc(b.en) + '</span><span class="b-zh">' + esc(b.zh) + '</span></' + tag + '>';
  }
  if (b.k === 'p') {
    return '<div class="blk blk-p" data-blk="' + b._bid + '" data-pi="' + b._pi + '">' +
      '<p class="t-en">' + sentHTML(b.en, 'en', b._pi) + '</p>' +
      '<p class="t-zh">' + sentHTML(b.zh, 'zh', b._pi) + '</p></div>';
  }
  if (b.k === 'eq') {
    return '<div class="blk eq" data-blk="' + b._bid + '">' +
