    return '<figure class="blk fig' + (b.span === 'full' ? ' span-full' : '') + '" data-blk="' + b._bid + '">' +
      '<div class="fig-frames' + (b.frames.length > 1 ? ' cols-2' : '') + '">' + frames + '</div>' +
      '<figcaption class="cap"><span class="cap-no">图 ' + b.no + ' · Figure ' + b.no + '</span>' +
