        '<span class="b-en">' + esc(b.capEn) + '</span><span class="b-zh">' + esc(b.capZh) + '</span></figcaption>' +
      '<div class="tbl-wrap"><table class="booktbl"><thead><tr>' +
        b.head.map(c => '<th>' + cellHTML(c) + '</th>').join('') +
      '</tr></thead><tbody>' +
        b.rows.map(r => '<tr>' + r.map(c => '<td>' + cellHTML(c) + '</td>').join('') + '</tr>').join('') +
