def split_en(text: str) -> list[str]:
    """英文切句：终止标点连同其后的引号/括号一起收尾，**后面必须跟空白**才算句末。

    「后面必须跟空白」这条很关键：`28.4`、`et al.`、`Fig. 2` 里的点后面不是空白，
    所以不会被切成两句（原型的做法，照抄）。
    """
    out: list[str] = []
    start = 0
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c not in ".!?":
            i += 1
            continue
        j = i + 1
        while j < n and text[j] in ".!?\"'”’)]":
            j += 1
        if j >= n or text[j].isspace():
            out.append(text[start:j])
            start = j
            i = j
        else:
            i += 1
    if start < n:
        out.append(text[start:])
    return [s for s in out if s.strip()]


def split_zh(text: str) -> list[str]:
    """中文切句：到 `。！？；…` 为止（标点留在句尾）。"""
    parts = re.findall(r"[^。！？；…]+[。！？；…]*", text or "")
    return [s for s in parts if s.strip()]


def sentence_spans(text: str, *, block_id: str, lang: str, typeset: bool) -> str:
    """把一段正文切成 `<span class="sn" data-sid="…">`（原型 `sentHTML`）。

    `sid` = `{块 ID}:{c|e}{句序号}` —— 句子的**稳定锚点**：高亮与笔记都存它。
    块 ID 进 sid 是刻意的：句序号（`c3`）只在块内有意义，两份数据若各存一半，
    笔记与高亮就得靠"再拼一次"才对得上。

    ⚠️ 切句必须在 `_mathy` **之前**做：`$…$` 要先保持 LaTeX 源码形态，
    否则公式已被渲染成 MathML，再按标点切就会切进标签里。
    """
    prefix = "c" if lang == "zh" else "e"
    pieces = split_zh(text) if lang == "zh" else split_en(text)
    if not pieces:
        return _mathy(text, typeset=typeset)
    out: list[str] = []
    for i, s in enumerate(pieces):
        sid = f"{block_id}:{prefix}{i}"
        label = _html.escape(s.strip()[:80], quote=True)
        out.append(
            f'<span class="sn" data-sid="{sid}" data-slang="{lang}" tabindex="0" role="button" '
            f'aria-label="{label}">{_mathy(s, typeset=typeset)}</span>'
        )
    return "".join(out)"}

