{"file_path": "/Users/argszero/scm/github.com/argszero/papershelf/web/src/pages/Reader.tsx", "new_string": "/** `sid` = `{块 ID}:{c|e}{句序号}`（服务端 `markup.sentence_spans` 生成）。
 * 块 ID 里不会有冒号（`b-0001`），但仍用**贪婪匹配**取前半段，免得将来放宽了格式就悄悄错位。 */
const SID_RE = /^(.+):([ce])(\d+)$/

function parseSid(sid: string): { blockId: string; lang: 'c' | 'e'; index: number } | null {
  const m = SID_RE.exec(sid || '')
  if (!m) return null
  return { blockId: m[1], lang: m[2] as 'c' | 'e', index: Number(m[3]) }
}

/** 「第 N 段 · 第 M 句（中文/原文）」—— 与原型 `noteTargetText` 同款文案。
 *
 * 段号（N）来自**正文段计数**（`paraIndex`），不是块序号：块序号里还混着标题、
 * 图表、公式，直接用会出现"第 137 段"这种对人不友好的数字。
 * 段号查不到（块已不存在 / 不是正文段）就退回块 ID —— 宁可能看懂，也别显示假段号。 */
function whereLabel(blockId: string | null | undefined, sid: string | null | undefined,
                    paraIndex: Map<string, number>): string {
  const parsed = parseSid(sid || '')
  const bid = parsed?.blockId || blockId || ''
  const ord = bid ? paraIndex.get(bid) : undefined
  const base = ord ? `第 ${ord} 段` : (bid || '文献级')
  if (!parsed) return base
  const lang = parsed.lang === 'c' ? '中文' : '原文'
  return `${base} · 第 ${parsed.index + 1} 句（${lang}）`
}

