  }

  /** 选中一句：读它的**当前渲染文本**当摘录（原型 `sentenceText`）。
   *
   * 摘录要在点击时取（而不是渲染时算）：句子文本只存在于服务端渲染的 HTML 里，
   * 渲染期读 DOM 拿不到（首帧还没有这些节点），而且它不该触发重渲染。
   * 摘录长度与原型一致上限 44 字 —— 它是列表里的一行引文，不是全文。 */
  function selectSentence(bid: string, sid: string) {
    setSel(bid)
    setSelSent(sid)
    setQuote(quoteOf(sid))
    // 选句 = 接下来多半要给它写笔记 → 右栏切到「笔记」（原型 `selectSent` 同款）
    setRail('notes')
  }

  function selectBlock(bid: string) {
    setSel(bid)
    setSelSent('')
    setQuote('')
  }

  function quoteOf(sid: string): string {
    const el = scrollRef.current?.querySelector<HTMLElement>(`[data-sid="${sid}"]`)
    return (el?.textContent || '').trim().slice(0, 44)
  }

  /** ㉚ 高亮/取消高亮当前选中的句子。
   *
   * **乐观更新**：先改本地状态（界面立刻有反馈），失败再回滚并把原因说出来。
   * 高亮是一记一键开关，等一个来回才变色会让人以为没点上。
   */
  async function toggleHighlight() {
    if (readonly || !selSent) return
    const sid = selSent
    const on = !highlights.has(sid)
    const apply = (v: boolean) => setHighlights((prev) => {
      const next = new Set(prev)
      if (v) next.add(sid); else next.delete(sid)
      return next
    })
    apply(on)
    try {
      if (on) await api.addHighlight(pid, sid)
      else await api.removeHighlight(pid, sid)
      flash(on ? '已高亮该句' : '已取消高亮')
    } catch (e) {
      apply(!on)
      flash(e instanceof Error ? e.message : '标注失败')
    }
  }

  /** 点击笔记 → 滚到对应句子并**闪一下**（原型 `goToNote`）。
   *
   * 两级落点：先找句子（`data-sid`），当前语言模式下这句被隐藏时退到整块（`data-b`）——
   * 「仅中文」模式里点一条原文笔记，句子节点确实存在但不可见，scrollIntoView 会算在 0 处。
