  function gotoNote(n: Note) {
    const stage = scrollRef.current
    if (!stage) return
    const sid = n.sid || ''
    let target = sid ? stage.querySelector<HTMLElement>(`[data-sid="${sid}"]`) : null
    if (target && target.offsetParent === null) target = null
