  const props = ['cursor', 'transitionProperty', 'transitionDuration', 'borderRadius',
    'backgroundColor', 'textDecorationLine', 'textDecorationThickness', 'textDecorationColor',
    'textUnderlineOffset', 'animationName', 'animationDuration', 'webkitBoxDecorationBreak',
