    host.innerHTML = html;
    const el = host.querySelector('[data-probe]');
    if (!el) { out[name] = 'MISSING'; continue; }
    const cs = getComputedStyle(el);
    const row = {};
    for (const p of props) row[p] = cs[p];
    out[name] = row;
