 * 若只挂 onClick，键盘用户点不动它（原型同时绑了两套事件）。 */
function NoteList({ notes, paraIndex, selSent, highlights, onGoto, onDelete, readonly }: {
  notes: Note[]
  paraIndex: Map<string, number>
  selSent: string
  highlights: Set<string>
  onGoto: (n: Note) => void
  onDelete: (id: number) => void
  readonly?: boolean
}) {
  if (notes.length === 0) {
    return (
      <p className="meta" style={{ textAlign: 'center', padding: '30px 8px', lineHeight: 1.7 }}>
        点击正文任意一句即可高亮，<br />或为它写下阅读笔记。
      </p>
    )
  }
  return (
    <>
      {notes.map((n) => {
        const sid = n.sid || ''
        const label = whereLabel(n.block_id, sid, paraIndex)
        return (
          <div className={`note-card${sid && sid === selSent ? ' is-on' : ''}`} key={n.id}
               tabIndex={0} role="button" aria-label={`跳转到 ${label}`}
               onClick={() => onGoto(n)}
               onKeyDown={(e) => {
                 if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onGoto(n) }
               }}>
            <div className="nc-head">
              <span className="nc-q">{label}</span>
              {/* 小圆点 = 这一句已高亮（原型 `.nc-hl`）：笔记列表就是"我标过的重点" */}
              {sid !== '' && highlights.has(sid) && <span className="nc-hl" title="已高亮" />}
              <span className="meta" style={{ marginLeft: 'auto' }}>{relTime(n.created_at)}</span>
