/** 笔记表单：锚定**当前选中**的句子或整块（原型没有"是否锚定"的开关 ——
 * 选了什么就是给什么写笔记，表单顶部那行字就是答案）。 */
function NoteForm({ paperId, blockId, sid, targetLabel, quote, highlighted,
                    onToggleHighlight, onAdded }: {
  paperId: number
  blockId: string | null
  sid: string | null
  targetLabel: string
  quote: string
  highlighted: boolean
  onToggleHighlight: () => void
  onAdded: (n: Note) => void
}) {
  const [text, setText] = useState('')
  const [busy, setBusy] = useState(false)

  async function add() {
    if (!text.trim()) return
    setBusy(true)
    try {
      const n = await api.addNote(paperId, text.trim(), blockId, sid, quote || null)
      onAdded(n)

      onAdded(n)
      setText('')
    } finally { setBusy(false) }
  }

  return (
    <div className="note-form">
      <div className="nf-target">{targetLabel}</div>
      {quote && <blockquote className="nf-quote">「{quote}」</blockquote>}
      {/* 高亮按钮只对**句子**有意义（整块高亮没有语义，原型同款：没选句就藏起来） */}
      {sid && (
        <button className={`btn btn-secondary btn-sm hl-btn${highlighted ? ' is-on' : ''}`}
                onClick={onToggleHighlight}>
          {highlighted ? '取消高亮' : '高亮此句'}
        </button>
      )}
      <textarea className="textarea" rows={3} value={text}
                placeholder="写下你的理解、疑问或可引用的要点…（Ctrl/Cmd + Enter 提交）"
                onChange={(e) => setText(e.target.value)}
                onKeyDown={(e) => { if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') void add() }} />
      <button className="btn btn-primary btn-sm" style={{ width: '100%', justifyContent: 'center', marginTop: 9 }}
              disabled={busy || !text.trim()} onClick={() => void add()}>
        保存笔记
      </button>
    </div>
  )
}
