function notesHTML(notes, pid) {
  if (!notes.length) return '<p class="meta" style="text-align:center;padding:30px 8px;line-height:1.7">点击正文任意一句即可高亮，<br>或为它写下阅读笔记。</p>';
  const hlm = (activePlan().highlights[pid]) || {};
  return notes.map(n => {
    const m = parseSid(n.sid);
    const where = m ? '第 ' + (m[0] + 1) + ' 段 · 第 ' + (m[2] + 1) + ' 句' : '第 ' + (n.pi + 1) + ' 段';
    return '<div class="note-card" data-goto="' + (n.sid || '') + '" data-gopi="' + n.pi + '" tabindex="0" role="button" aria-label="跳转到 ' + where + '">' +
      '<div class="nc-head"><span class="nc-q">' + where + '</span>' +
      (n.sid && hlm[n.sid] ? '<span class="nc-hl" title="已高亮"></span>' : '') +
      '<button class="nc-del" data-del="' + n.id + '" aria-label="删除笔记">×</button></div>' +
      (n.quote ? '<div class="nc-q2">「' + esc(n.quote) + '」</div>' : '') +
      '<div class="nc-t">' + esc(n.text) + '</div></div>';
  }).join('');
}
function outlineHTML() {
  return OUTLINE.map(o => '<div class="outline-item lv' + o.lvl + '" data-jump="' + esc(o.sec) + '"><span class="oi-n">' + esc(o.n) + '</span>' + esc(o.label) + '</div>').join('') +
    '<p class="meta" style="margin-top:14px;line-height:1.7">章节按原文顺序排列，点击可跳转；图 1、图 2 与表 1 都保留在 PDF 中的原始位置。</p>';
}
function noteTargetText() {
  if (state.selSent) { const m = parseSid(state.selSent); if (m) return '第 ' + (m[0] + 1) + ' 段 · 第 ' + (m[2] + 1) + ' 句' + (m[1] === 'c' ? '（中文）' : '（原文）'); }
  if (state.selPara != null) return '第 ' + (state.selPara + 1) + ' 段';
  return '点击正文句子后添加笔记';
}
function noteForm(pid) {
  const quote = state.selSent ? sentenceText(state.selSent) : '';
  const on = state.selSent && ((activePlan().highlights[pid] || {})[state.selSent]);
  return '<div class="note-form"><div class="nf-target">' + noteTargetText() + '</div>' +
    (quote ? '<blockquote class="nf-quote">「' + esc(quote) + '」</blockquote>' : '') +
    '<button class="btn btn-secondary btn-sm hl-btn' + (on ? ' is-on' : '') + '" id="hlToggle"' + (state.selSent ? '' : ' style="display:none"') + '>' + (on ? '取消高亮' : '高亮此句') + '</button>' +
    '<textarea class="textarea" id="noteInput" placeholder="写下你的理解、疑问或可引用的要点…" aria-label="笔记内容"></textarea>' +
    '<button class="btn btn-primary btn-sm save-btn" id="addNote">保存笔记</button></div>';
}
function sentenceText(sid) {
  const el = $('#docStage [data-sid="' + sid + '"]');
  return el ? el.textContent.trim() : '';
}
function syncNoteForm(pid) {
  const form = $('.note-form'); if (!form) return;
  const sid = state.selSent;
  const t = form.querySelector('.nf-target');
  if (t) t.textContent = noteTargetText();
  const quote = sid ? sentenceText(sid) : '';
  let q = form.querySelector('.nf-quote');
  if (quote) {
    if (!q) { q = document.createElement('blockquote'); q.className = 'nf-quote'; if (t) t.insertAdjacentElement('afterend', q); else form.prepend(q); }
    q.textContent = '「' + quote + '」';
  } else if (q) q.remove();
  const hb = form.querySelector('#hlToggle');
  if (hb) {
    const on = sid && !!((activePlan().highlights[pid] || {})[sid]);
    hb.textContent = on ? '取消高亮' : '高亮此句';
    hb.classList.toggle('is-on', !!on);
    hb.style.display = sid ? '' : 'none';
  }
}
function addNote(pid, flat) {
  if (SHARE.active) { toast('只读分享无法编辑笔记'); return; }
  const ta = $('#noteInput'); if (!ta || !ta.value.trim()) { toast('请先输入笔记内容'); return; }
  const pi = state.selPara != null ? state.selPara : 0;
  const sid = state.selSent || null;
  const list = activePlan().notes[pid] = activePlan().notes[pid] || [];
  const q = sid ? sentenceText(sid) : ((flat[pi] && flat[pi].zh) ? flat[pi].zh : '');
  list.unshift({ id: 'n' + Date.now(), pi, sid, text: ta.value.trim(), quote: q.slice(0, 44) });
  save(); renderReader(); renderShell(); toast('笔记已保存');
}
function bindNoteDel(pid) { if (SHARE.active) return; $$('#view [data-del]').forEach(b => b.addEventListener('click', e => { e.stopPropagation(); activePlan().notes[pid] = (activePlan().notes[pid] || []).filter(n => n.id !== b.dataset.del); save(); renderReader(); renderShell(); })); }
function bindNoteGoto(pid) {
  $$('#view .note-card').forEach(c => {
    const go = () => goToNote(pid, c.dataset.goto || '', +c.dataset.gopi);
    c.addEventListener('click', go);
    c.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(); } });
  });
}

