    naked = re.sub(r"/\*.*?\*/", "", css, flags=re.S)
    for selector in (".nc-hl", ".nc-q2", ".nf-quote", ".hl-btn", ".note-card.is-on"):
        assert selector in naked, f"缺少 {selector}（与原型同名，改了名就等于悄悄丢功能）"


