                    <h1 className="doc-title">
                      {mode !== 'zh' && <span className="b-en">{String(meta.title_en || title)}</span>}
                      {mode !== 'en' && meta.title_zh && <span className="b-zh">{String(meta.title_zh)}</span>}
                    </h1>
