      out += '<mark class="hl hl-' + m.color + '" data-h="' + m.id + '" tabindex="0" role="mark" aria-label="' +
        esc(text.slice(s, e).trim().slice(0, 80)) + '">' + esc(text.slice(s, e)) + '</mark>' +
